-- ================================================================-- MIGRACIÓN 2026-05-03 — Skills MCP: Webhooks, Cron, Category Mapping-- ================================================================-- 1. Columnas nuevas en meli_accounts (Invalid Grant Handler)ALTER TABLE meli_accounts ADD COLUMN IF NOT EXISTS needs_reauth BOOLEAN DEFAULT false;ALTER TABLE meli_accounts ADD COLUMN IF NOT EXISTS reauth_error TEXT;-- 2. Tabla: Notificaciones Push de MercadoLibre (Webhooks)CREATE TABLE IF NOT EXISTS ml_notifications (  id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),  created_at      TIMESTAMPTZ DEFAULT NOW(),  processed_at    TIMESTAMPTZ,  topic           TEXT NOT NULL,           -- items, orders_v2, questions, shipments, payments  resource        TEXT NOT NULL,           -- /orders/123456, /items/MLV123  user_id         BIGINT NOT NULL,         -- meli_user_id que generó el evento  application_id  BIGINT,  attempts        INTEGER DEFAULT 1,       -- intentos de envío de ML  payload         JSONB,                   -- JSON completo de la notificación  status          TEXT DEFAULT 'pending',  -- pending, processing, completed, error  error_message   TEXT,  ml_sent_at      TIMESTAMPTZ,             -- timestamp que envió ML  ml_received_at  TIMESTAMPTZ              -- timestamp que recibió ML);-- 3. Tabla: Mapeo de Categorías Internas → MercadoLibreCREATE TABLE IF NOT EXISTS category_mappings (  id                      UUID PRIMARY KEY DEFAULT gen_random_uuid(),  created_at              TIMESTAMPTZ DEFAULT NOW(),  updated_at              TIMESTAMPTZ DEFAULT NOW(),  internal_line_code      TEXT NOT NULL,   -- ej: 11-000  internal_subline_code   TEXT NOT NULL,   -- ej: 11-001  internal_name           TEXT NOT NULL,   -- ej: AMORTIGUADOR NORMAL  ml_category_id          TEXT,            -- ej: MLA1747 (o subcategoría hoja)  ml_category_name        TEXT,  ml_domain_id            TEXT,  ml_domain_name          TEXT,  is_validated            BOOLEAN DEFAULT false,  -- true cuando un usuario confirmó el mapeo  validated_by            TEXT,                     -- usuario que validó  validated_at            TIMESTAMPTZ,  UNIQUE(internal_line_code, internal_subline_code));-- 4. Trigger para updated_at en category_mappingsCREATE OR REPLACE FUNCTION update_updated_at()RETURNS TRIGGER AS $$BEGIN  NEW.updated_at = NOW();  RETURN NEW;END;$$ LANGUAGE plpgsql;CREATE OR REPLACE TRIGGER update_category_mappings_updated_at  BEFORE UPDATE ON category_mappings FOR EACH ROW EXECUTE FUNCTION update_updated_at();-- 5. Índices para notificacionesCREATE INDEX IF NOT EXISTS idx_notifications_status ON ml_notifications(status);CREATE INDEX IF NOT EXISTS idx_notifications_topic ON ml_notifications(topic);CREATE INDEX IF NOT EXISTS idx_notifications_user ON ml_notifications(user_id);CREATE INDEX IF NOT EXISTS idx_notifications_created ON ml_notifications(created_at);-- 6. Índices para mapeo de categoríasCREATE INDEX IF NOT EXISTS idx_catmap_line ON category_mappings(internal_line_code);CREATE INDEX IF NOT EXISTS idx_catmap_subline ON category_mappings(internal_subline_code);CREATE INDEX IF NOT EXISTS idx_catmap_ml_cat ON category_mappings(ml_category_id);CREATE INDEX IF NOT EXISTS idx_catmap_validated ON category_mappings(is_validated);-- ================================================================-- ✅ Migración completada exitosamente.-- ================================================================